  model: 'openai/gpt-5.6-sol',
  input: 'My favorite programming language is Rust.',
  store: true,
});
console.log(first.id);

const followUp = await client.responses.create({
  model: 'openai/gpt-5.6-sol',
  previous_response_id: first.id,
