## Add embeddings to an existing project

A standalone script that embeds a few strings and prints vectors proves the key works, but nothing in your app calls it, so your users never see a result. Instead, one module owns the client, an indexing function takes the records your app already has and saves each vector where that record already lives, and an existing route or view calls a ranking function that reads those stored vectors. The example below adds related help articles to a support app, with Python under `app/` and TypeScript under `src/`.

**1. Create one embeddings module**

Put the client in a single module so the model ID, batching, decoding, and similarity metric live in one place. The library reads `PERPLEXITY_API_KEY` from the environment; do not pass the key in code or commit it. `embed` returns the base64 int8 strings the API sends back. Store that string with the record (a text column, a JSON field, or a document property) and decode it when you compare.

Python: `app/embeddings.py`. TypeScript: `src/embeddings.ts`.

```python Python theme={null}
import base64
from typing import Final

import numpy as np
from perplexity import Perplexity

MODEL: Final = "pplx-embed-v1-4b"
# A request takes up to 512 texts and 120,000 tokens in total. Lower this if your records are long.
BATCH_SIZE = 100

_client: Perplexity | None = None

def client() -> Perplexity:
    """One client per process. Reads PERPLEXITY_API_KEY from the environment."""
    global _client
    if _client is None:
        _client = Perplexity()
    return _client

def embed(texts: list[str]) -> list[str]:
    """Return one base64 int8 embedding per input text, in input order."""
    out: list[str] = []
    for i in range(0, len(texts), BATCH_SIZE):
        response = client().embeddings.create(input=texts[i : i + BATCH_SIZE], model=MODEL)
        for item in sorted(response.data or [], key=lambda d: d.index or 0):
            if not item.embedding:
                raise RuntimeError(f"Embeddings API returned no embedding for input {item.index}")
            out.append(item.embedding)
    return out

def decode(b64: str) -> np.ndarray:
    """Decode a stored base64 int8 embedding to float32."""
    return np.frombuffer(base64.b64decode(b64), dtype=np.int8).astype(np.float32)

def cosine_similarity(a: np.ndarray, b: np.ndarray) -> float:
    """Perplexity embeddings are unnormalized. Compare with cosine, not a raw dot product."""
    return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b)))
```

```typescript Typescript theme={null}
import Perplexity from '@perplexity-ai/perplexity_ai';

export const MODEL = "pplx-embed-v1-4b";
// A request takes up to 512 texts and 120,000 tokens in total. Lower this if your records are long.
const BATCH_SIZE = 100;

let client: Perplexity | undefined;

function getClient(): Perplexity {
    // One client per process. The SDK reads PERPLEXITY_API_KEY from the environment.
    if (!client) {
        client = new Perplexity();
    }
    return client;
}

export async function embed(texts: string[]): Promise<string[]> {
    // Return one base64 int8 embedding per input text, in input order.
    const out: string[] = [];
    for (let i = 0; i < texts.length; i += BATCH_SIZE) {
        const response = await getClient().embeddings.create({
            input: texts.slice(i, i + BATCH_SIZE),
            model: MODEL,
        });
        const items = [...(response.data ?? [])].sort((a, b) => (a.index ?? 0) - (b.index ?? 0));
        for (const item of items) {
            if (!item.embedding) {
                throw new Error(`Embeddings API returned no embedding for input ${item.index}`);
            }
            out.push(item.embedding);
        }
    }
    return out;
}

export function decode(b64: string): Float32Array {
    // Decode a stored base64 int8 embedding to float32.
    const buffer = Buffer.from(b64, 'base64');
    const int8 = new Int8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength);
    return Float32Array.from(int8);
}

export function cosineSimilarity(a: Float32Array, b: Float32Array): number {
    // Perplexity embeddings are unnormalized. Compare with cosine, not a raw dot product.
    let dot = 0, normA = 0, normB = 0;
    for (let i = 0; i < a.length; i++) {
        dot += a[i] * b[i];
        normA += a[i] * a[i];
        normB += b[i] * b[i];
    }
    return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}
```

**2. Index the records your app already has, then rank from storage**

Two functions, both working against the app's existing article store. `index_articles` embeds every article that has body text and no vector yet and saves the vector on that article through the store the app already uses. `related_articles` embeds only the incoming question and ranks the stored vectors. Neither builds its own client, and the embedding function is a parameter with a default so tests can pass a fake. When an article's body changes, clear its stored embedding (`None` in Python, `null` in TypeScript) in the same update so the next `index_articles` run embeds the new text.

Python: `app/support/related_articles.py`. TypeScript: `src/support/relatedArticles.ts`.

```python Python theme={null}
from collections.abc import Callable
from typing import Protocol

from app.embeddings import cosine_similarity, decode, embed

class Article(Protocol):
    id: str
    body: str
    embedding: str | None  # base64 int8 from the Embeddings API, stored with the row

class ArticleStore(Protocol):
    def all(self) -> list[Article]: ...
    def save_embedding(self, article_id: str, embedding: str) -> None: ...

EmbedFn = Callable[[list[str]], list[str]]

def index_articles(store: ArticleStore, embed_fn: EmbedFn = embed) -> int:
    """Embed articles that have no vector yet and save each vector on its article.

    Call this from the existing publish hook, or once as a backfill.
    """
    # The API rejects empty strings, so skip articles with no body text.
    pending = [article for article in store.all() if article.embedding is None and article.body.strip()]
    if not pending:
        return 0
    for article, vector in zip(pending, embed_fn([article.body for article in pending]), strict=True):
        store.save_embedding(article.id, vector)
    return len(pending)

def related_articles(
    question: str,
    store: ArticleStore,
    top_k: int = 3,
    embed_fn: EmbedFn = embed,
) -> list[tuple[Article, float]]:
    """Rank indexed articles by similarity to a customer question.

    Called from the existing ticket view, where it replaces a keyword match.
    """
    indexed = [(article, article.embedding) for article in store.all() if article.embedding is not None]
    if not indexed:
        return []
    question_vector = decode(embed_fn([question])[0])
    scored = [(article, cosine_similarity(question_vector, decode(vector))) for article, vector in indexed]
    scored.sort(key=lambda pair: pair[1], reverse=True)
    return scored[:top_k]
```

```typescript Typescript theme={null}
import { cosineSimilarity, decode, embed } from '../embeddings';

export interface Article {
    id: string;
    body: string;
    embedding: string | null; // base64 int8 from the Embeddings API, stored with the record
}

export interface ArticleStore {
    all(): Promise<Article[]>;
    saveEmbedding(articleId: string, embedding: string): Promise<void>;
}

export type EmbedFn = (texts: string[]) => Promise<string[]>;

// Embed articles that have no vector yet and save each vector on its article.
// Call this from the existing publish hook, or once as a backfill.
export async function indexArticles(store: ArticleStore, embedFn: EmbedFn = embed): Promise<number> {
    // The API rejects empty strings, so skip articles with no body text.
    const pending = (await store.all()).filter((article) => article.embedding === null && article.body.trim() !== '');
    if (pending.length === 0) {
        return 0;
    }
    const vectors = await embedFn(pending.map((article) => article.body));
    if (vectors.length !== pending.length) {
        throw new Error(`Expected ${pending.length} embeddings, got ${vectors.length}`);
    }
    for (const [i, article] of pending.entries()) {
        await store.saveEmbedding(article.id, vectors[i]);
    }
    return pending.length;
}

// Rank indexed articles by similarity to a customer question.
// Called from the existing ticket view, where it replaces a keyword match.
export async function relatedArticles(
    question: string,
    store: ArticleStore,
    topK = 3,
    embedFn: EmbedFn = embed,
): Promise<Array<{ article: Article; score: number }>> {
    const indexed = (await store.all()).filter((article) => article.embedding !== null);
    if (indexed.length === 0) {
        return [];
    }
    const [questionVector] = (await embedFn([question])).map(decode);
    return indexed
        .map((article) => ({ article, score: cosineSimilarity(questionVector, decode(article.embedding as string)) }))
        .sort((a, b) => b.score - a.score)
        .slice(0, topK);
}
```

