**3. Test the caller, then run the whole suite**

Test the feature, not the API. With an in-memory store and a fake embedding function, check that indexing saves a vector on each article that lacked one, and that ranking uses cosine similarity (a large-magnitude vector must not win on dot product alone). One live check runs only when `PERPLEXITY_API_KEY` is set.

Python: `tests/test_related_articles.py`. TypeScript: `tests/relatedArticles.test.ts`.

```python Python theme={null}
import base64
import os
from dataclasses import dataclass

import numpy as np
import pytest

from app.support.related_articles import index_articles, related_articles

@dataclass
class Article:
    id: str
    body: str
    embedding: str | None = None

class MemoryStore:
    def __init__(self, articles):
        self.articles = {article.id: article for article in articles}

    def all(self):
        return list(self.articles.values())

    def save_embedding(self, article_id, embedding):
        self.articles[article_id].embedding = embedding

def b64(*values):
    """Build a base64 int8 string the way the API returns one."""
    return base64.b64encode(np.array(values, dtype=np.int8).tobytes()).decode()

ARTICLES = [
    Article("reset-password", "How to reset your password from the login page."),
    Article("export-data", "Export your workspace data as CSV or JSON."),
    Article("billing", "Update the card on file and download invoices."),
]
QUESTION = "I need to download all my data"
# The billing vector has the largest dot product with the question.
# Cosine similarity must still rank the export article first.
FAKE = {
    QUESTION: b64(1, 0, 0),
    ARTICLES[0].body: b64(0, 1, 0),
    ARTICLES[1].body: b64(20, 1, 0),
    ARTICLES[2].body: b64(50, 60, 0),
}

def fake_embed(texts):
    return [FAKE[text] for text in texts]

def fresh_store():
    return MemoryStore([Article(article.id, article.body) for article in ARTICLES])

def test_index_saves_a_vector_on_each_unindexed_article():
    store = fresh_store()
    assert index_articles(store, embed_fn=fake_embed) == 3
    assert all(article.embedding for article in store.all())
    assert index_articles(store, embed_fn=fake_embed) == 0  # nothing left to embed

def test_ranks_by_cosine_not_magnitude():
    store = fresh_store()
    index_articles(store, embed_fn=fake_embed)
    [(article, score)] = related_articles(QUESTION, store, top_k=1, embed_fn=fake_embed)
    assert article.id == "export-data"
    assert 0.99 < score <= 1.0

@pytest.mark.skipif("PERPLEXITY_API_KEY" not in os.environ, reason="live check needs an API key")
def test_live_ranking():
    store = fresh_store()
    index_articles(store)
    [(article, _)] = related_articles("I forgot my password", store, top_k=1)
    assert article.id == "reset-password"
```

